// smallest payloads browsers actually decode, for tests that render real media
export const PNG_BYTES = Uint8Array.from(
  atob(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABAQMAAAAl21bKAAAAA1BMVEX/AAAZ4gk3AAAACklEQVQI12NgAAAAAgAB4iG8MwAAAABJRU5ErkJggg=="
  ),
  (c) => c.charCodeAt(0)
);
export const WEBM_BYTES = Uint8Array.from(
  atob(
    ""
  ),
  (c) => c.charCodeAt(0)
);
